using System;
using System.Collections.Generic;

public sealed class MonsterGrid
{
    private const int None = -1;

    private readonly float _invCell;
    private readonly int _originCellX, _originCellY; // 0번 열/행의 월드 기준 셀 좌표
    private readonly int _cols, _rows;

    private readonly int[] _cellHead; // 각 셀의 첫 몬스터 id (없으면 None)
    private readonly int[] _next;     // 몬스터 id로 인덱싱하는 침습형 이중 연결 리스트
    private readonly int[] _prev;
    private readonly int[] _cellOf;   // 몬스터가 속한 셀 인덱스 (미등록이면 None)
    private readonly float[] _x;
    private readonly float[] _y;

    public MonsterGrid(float minX, float minY, float maxX, float maxY,
                       float cellSize, int maxMonsters)
    {
        if (!(cellSize > 0f)) throw new ArgumentOutOfRangeException(nameof(cellSize));
        if (!(maxX > minX) || !(maxY > minY)) throw new ArgumentException("empty world bounds");
        if (maxMonsters < 0) throw new ArgumentOutOfRangeException(nameof(maxMonsters));

        _invCell = 1f / cellSize;
        _originCellX = (int)MathF.Floor(minX * _invCell);
        _originCellY = (int)MathF.Floor(minY * _invCell);
        _cols = (int)MathF.Floor(maxX * _invCell) - _originCellX + 1;
        _rows = (int)MathF.Floor(maxY * _invCell) - _originCellY + 1;

        _cellHead = new int[_cols * _rows];
        Array.Fill(_cellHead, None);
        _next = new int[maxMonsters];
        _prev = new int[maxMonsters];
        _cellOf = new int[maxMonsters];
        Array.Fill(_cellOf, None);
        _x = new float[maxMonsters];
        _y = new float[maxMonsters];
    }

    public void Insert(int id, float x, float y)
    {
        if (_cellOf[id] != None) throw new InvalidOperationException("id already inserted");
        _x[id] = x;
        _y[id] = y;
        Link(id, CellIndex(x, y));
    }

    public void Update(int id, float x, float y)
    {
        int oldCell = _cellOf[id];
        if (oldCell == None) throw new InvalidOperationException("id not inserted");
        _x[id] = x;
        _y[id] = y;
        int newCell = CellIndex(x, y);
        if (newCell == oldCell) return; // 대부분의 이동은 같은 셀 안에서 끝난다
        Unlink(id);
        Link(id, newCell);
    }

    public bool Remove(int id)
    {
        if (_cellOf[id] == None) return false;
        Unlink(id);
        return true;
    }

    public int QueryCircle(float cx, float cy, float radius, List<int> results)
    {
        results.Clear();
        if (!(radius >= 0f)) return 0; // 음수 또는 NaN 반지름

        // Broad phase: 원의 바운딩 박스가 걸치는 셀 범위 (그리드 범위로 클램프됨)
        int x0 = CellX(cx - radius), x1 = CellX(cx + radius);
        int y0 = CellY(cy - radius), y1 = CellY(cy + radius);
        float r2 = radius * radius;

        for (int gy = y0; gy <= y1; gy++)
        {
            int row = gy * _cols;
            for (int gx = x0; gx <= x1; gx++)
            {
                for (int id = _cellHead[row + gx]; id != None; id = _next[id])
                {
                    // Narrow phase: 제곱 거리로 정확히 판정 (경계 포함)
                    float dx = _x[id] - cx;
                    float dy = _y[id] - cy;
                    if (dx * dx + dy * dy <= r2) results.Add(id);
                }
            }
        }
        return results.Count;
    }

    // (int) 캐스트가 아니라 Floor: (int)(-0.5f) == 0 이지만 -0.5 는 셀 -1 에 속한다.
    // float 상태에서 먼저 클램프해 아주 먼 좌표나 NaN 이 int 변환에서 넘치지 않게 한다.
    private int CellX(float x)
    {
        float c = MathF.Floor(x * _invCell) - _originCellX;
        if (!(c > 0f)) return 0;           // 그리드 왼쪽 밖(또는 NaN) -> 가장자리 열
        if (c >= _cols) return _cols - 1;  // 그리드 오른쪽 밖 -> 가장자리 열
        return (int)c;
    }

    private int CellY(float y)
    {
        float c = MathF.Floor(y * _invCell) - _originCellY;
        if (!(c > 0f)) return 0;
        if (c >= _rows) return _rows - 1;
        return (int)c;
    }

    private int CellIndex(float x, float y) => CellY(y) * _cols + CellX(x);

    private void Link(int id, int cell)
    {
        int head = _cellHead[cell];
        _prev[id] = None;
        _next[id] = head;
        if (head != None) _prev[head] = id;
        _cellHead[cell] = id;
        _cellOf[id] = cell;
    }

    private void Unlink(int id)
    {
        int p = _prev[id], n = _next[id];
        if (p != None) _next[p] = n;
        else _cellHead[_cellOf[id]] = n;
        if (n != None) _prev[n] = p;
        _cellOf[id] = None;
    }
}

