public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 스크립트: "P A 10" = Push, "U A 40" = Update, "O" = Pop. 끝나면 남은 것을 모두 Pop.
    // 반환: "A@10 B@20" 형태의 Pop 순서
    static string Play(string script)
    {
        var h = new MinHeap();
        var sb = new System.Text.StringBuilder();
        foreach (string raw in script.Split(';'))
        {
            string[] t = raw.Trim().Split(' ');
            if (t[0] == "P") h.Push(t[1][0] - 'A', long.Parse(t[2]));
            else if (t[0] == "U") h.Update(t[1][0] - 'A', long.Parse(t[2]));
            else if (t[0] == "O") Append(sb, h.Pop());
        }
        while (h.Count > 0) Append(sb, h.Pop());
        return sb.ToString().Trim();
    }

    static void Append(System.Text.StringBuilder sb, HeapEntry e)
    {
        sb.Append((char)('A' + e.Id)).Append('@').Append(e.Priority).Append(' ');
    }

    static string Expect(string script, string expected)
    {
        string got = Play(script);
        return got == expected ? null : "입력 [" + script + "] 기대 " + expected + " / 결과 " + got;
    }

    public static void Main()
    {
        Run("basic-order", () =>
        {
            var h = new MinHeap();
            if (h.Count != 0) return "빈 힙의 Count 가 0 이 아님";
            h.Push(0, 50); h.Push(1, 30);
            if (h.Count != 2) return "Push 2회 후 Count 가 2 가 아님";
            HeapEntry e = h.Pop();
            if (e.Id != 1 || e.Priority != 30 || h.Count != 1) return "Pop 이 최솟값(B@30)을 반환하지 않음";
            return Expect("P A 50; P B 30; P C 80; P D 10; P E 60", "D@10 B@30 A@50 E@60 C@80")
                ?? Expect("P A 7", "A@7") ?? Expect("P A 2; P B 1", "B@1 A@2");
        });

        Run("sift-down-both-children", () =>
            Expect("P A 1; P B 3; P C 2; P D 4", "A@1 C@2 B@3 D@4")
            ?? Expect("P A 1; P B 9; P C 5; P D 10; P E 11; P F 6; P G 7", "A@1 C@5 F@6 G@7 B@9 D@10 E@11"));

        Run("stable-tie-order", () =>
            Expect("P A 10; P B 10; P C 10", "A@10 B@10 C@10")
            ?? Expect("P A 5; P B 5; P C 5; P D 5; P E 5; P F 5", "A@5 B@5 C@5 D@5 E@5 F@5")
            ?? Expect("P A 20; P B 10; P C 20; P D 10; P E 20", "B@10 D@10 A@20 C@20 E@20"));

        Run("atb-requeue-order", () =>
            // 꺼낸 유닛을 같은 틱으로 다시 넣으면 기존 동률 유닛 뒤에 선다
            Expect("P A 10; P B 20; P C 20; O; P A 20; O; P B 30", "A@10 B@20 C@20 A@20 B@30"));

        Run("update-increase", () =>
            Expect("P A 10; P B 20; P C 30; U A 40", "B@20 C@30 A@40")
            ?? Expect("P A 1; P B 2; P C 3; P D 4; P E 5; P F 6; P G 7; U B 100; U A 50", "C@3 D@4 E@5 F@6 G@7 A@50 B@100"));

        Run("update-decrease", () =>
            Expect("P A 10; P B 20; P C 30; U C 5", "C@5 A@10 B@20")
            ?? Expect("P A 1; P B 2; P C 3; P D 4; P E 5; P F 6; P G 7; U G 0; U E 1", "G@0 A@1 E@1 B@2 C@3 D@4 F@6"));

        Run("update-tie-and-missing", () =>
        {
            string e = Expect("P A 10; P B 20; U A 20", "B@20 A@20");
            if (e != null) return "Update 된 항목은 동률에서 뒤로 가야 함. " + e;
            e = Expect("P A 20; P B 20; U A 20", "B@20 A@20") ?? Expect("P A 5; P B 5; P C 5; P D 5; U A 5; U B 5", "C@5 D@5 A@5 B@5");
            if (e != null) return "같은 값으로 Update 해도 그 시점에 새로 들어온 것으로 취급해야 함. " + e;
            var h = new MinHeap();
            h.Push(0, 5); h.Push(1, 6);
            if (h.Update(9, 1)) return "힙에 없는 Id 의 Update 가 true 를 반환";
            if (!h.Update(1, 4)) return "힙에 있는 Id 의 Update 가 false 를 반환";
            if (h.Count != 2) return "Update 후 Count 가 변함";
            HeapEntry top = h.Pop();
            return top.Id == 1 && top.Priority == 4 ? null : "Update(B, 4) 후 Pop 이 B@4 가 아님";
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(12345);
            for (int run = 0; run < 60; run++)
            {
                var h = new MinHeap();
                // 기준 모델: (priority, seq, id) 목록에서 사전식 최솟값을 꺼낸다
                var model = new System.Collections.Generic.List<long[]>();
                long seq = 0; int nextId = 0;
                int range = run % 3 == 0 ? 4 : (run % 3 == 1 ? 50 : 1000000);
                for (int k = 0; k < 300; k++)
                {
                    int c = rng.Next(100);
                    if (model.Count == 0 || c < 40)
                    {
                        long p = rng.Next(range);
                        h.Push(nextId, p); model.Add(new long[] { p, seq++, nextId }); nextId++;
                    }
                    else if (c < 65)
                    {
                        int j = rng.Next(model.Count); long p = rng.Next(range);
                        h.Update((int)model[j][2], p);
                        model[j] = new long[] { p, seq++, model[j][2] };
                    }
                    else
                    {
                        int best = 0;
                        for (int j = 1; j < model.Count; j++)
                            if (model[j][0] < model[best][0] || (model[j][0] == model[best][0] && model[j][1] < model[best][1])) best = j;
                        long[] m = model[best]; model.RemoveAt(best);
                        HeapEntry e = h.Pop();
                        if (e.Id != m[2] || e.Priority != m[0])
                            return "무작위 연산 " + run + "회차 " + k + "번째: 기대 Id " + m[2] + "@" + m[0] + " / 결과 Id " + e.Id + "@" + e.Priority;
                    }
                    if (h.Count != model.Count) return "Count 불일치: 기대 " + model.Count + " / 결과 " + h.Count;
                }
            }
            return null;
        });
    }
